/// A KPI spec, as cortext's KPI registry stores it: one governed object per
/// KPI — a metric over ontology-typed data plus a pass rule — homed in the
/// `.models` system directory beside `ModelManifest`, `OntologyDeclaration`
/// and `Mission` (the same governed-object recipe), with an ACL the owner
/// controls and the platform's own revision history.
///
/// The object is a *reference*, like the kinds before it: the spec's YAML is a
/// Drive file named here by id, content revision and sha256, and the fields a
/// listing reads (the key, the title, the version, the service system, who
/// published it and when) are projected once per source revision into the
/// `kpi_specs` registry (registry.fbs). Unlike a skill or a source note the
/// source is structured — the registry reads it as YAML and projects the
/// concepts the metric reads as a relation, so "which KPIs read
/// `ul:AssetExposureLevel`" is answered by a relation table and not by opening
/// records. A run records the object revision that judged it, so provenance
/// can serve the rule that was in force rather than the file as it reads now.
#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct KpiSpec {
    /// The principal whose write this revision is (oid).
    pub authored_by: Option<String>,
    /// That file's content revision at this write.
    pub document_cid: Option<ContentId>,
    /// The Drive file object holding the spec (YAML).
    pub document_id: ObjectId,
    /// sha256 (hex) of the document bytes; the projector verifies it.
    pub document_sha256: String,
    /// The KPI's id, permanent and unique; the object id derives from it, so a
    /// re-registration of the same KPI revises the same object.
    pub kpi: String,
    /// When this revision was published, ms since the epoch (UTC).
    pub published_at: i64,
    /// The service system the KPI judges (transportation, emergency, ...).
    pub service_system: Option<String>,
    /// What the KPI measures, as its document titles it.
    pub title: Option<String>,
    /// The spec's authored version, as its document declares it.
    pub version: i32,
}

impl KpiSpec {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsKpiSpec<'a>> {
        use crate::types::generated::kpi_spec_generated::KpiSpecBuilder as FbsKpiSpecBuilder;

        let authored_by_offset = self.authored_by.as_ref().map(|s| builder.create_string(s));
        let document_cid_offset = self.document_cid.as_ref().map(|o| o.serialize_to(builder));
        let document_id_offset = self.document_id.serialize_to(builder);
        let document_sha256_offset = builder.create_string(&self.document_sha256);
        let kpi_offset = builder.create_string(&self.kpi);
        let service_system_offset = self
            .service_system
            .as_ref()
            .map(|s| builder.create_string(s));
        let title_offset = self.title.as_ref().map(|s| builder.create_string(s));

        let mut bldr = FbsKpiSpecBuilder::new(builder);
        if let Some(offset) = authored_by_offset {
            bldr.add_authored_by(offset);
        }
        if let Some(offset) = document_cid_offset {
            bldr.add_document_cid(offset);
        }
        bldr.add_document_id(document_id_offset);
        bldr.add_document_sha256(document_sha256_offset);
        bldr.add_kpi(kpi_offset);
        bldr.add_published_at(self.published_at);
        if let Some(offset) = service_system_offset {
            bldr.add_service_system(offset);
        }
        if let Some(offset) = title_offset {
            bldr.add_title(offset);
        }
        bldr.add_version(self.version);
        bldr.finish()
    }
}

impl From<FbsKpiSpec<'_>> for KpiSpec {
    fn from(fbs: FbsKpiSpec<'_>) -> Self {
        let authored_by = fbs.authored_by().map(ToOwned::to_owned);
        let document_cid = fbs.document_cid().map(ContentId::from);
        let document_id = ObjectId::from(fbs.document_id());
        let document_sha256 = fbs.document_sha256().to_owned();
        let kpi = fbs.kpi().to_owned();
        let published_at = fbs.published_at();
        let service_system = fbs.service_system().map(ToOwned::to_owned);
        let title = fbs.title().map(ToOwned::to_owned);
        let version = fbs.version();
        Self {
            authored_by,
            document_cid,
            document_id,
            document_sha256,
            kpi,
            published_at,
            service_system,
            title,
            version,
        }
    }
}

impl crate::FbsSerde for KpiSpec {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsKpiSpec>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

